import{_ as e,o as i,c as o,a3 as a}from"./chunks/framework.BMJIGmOB.js";const g=JSON.parse('{"title":"用 GitHub + PicGo 搭建自己的图床","description":"把 Typora 里的本地图片自动传到 GitHub，再用 jsDelivr 加速，一次配置长期可用。","frontmatter":{"title":"用 GitHub + PicGo 搭建自己的图床","description":"把 Typora 里的本地图片自动传到 GitHub，再用 jsDelivr 加速，一次配置长期可用。","date":"2026-11-15T00:00:00.000Z","category":"工善利器","subCategory":"工具箱","tags":["图床","PicGo","GitHub","Typora"],"author":"闲生"},"headers":[],"relativePath":"posts/tools/toolbox/github-image-hosting.md","filePath":"posts/tools/toolbox/github-image-hosting.md"}'),r={name:"posts/tools/toolbox/github-image-hosting.md"};function c(s,t,d,p,n,l){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="用-github-picgo-搭建自己的图床" tabindex="-1">用 GitHub + PicGo 搭建自己的图床 <a class="header-anchor" href="#用-github-picgo-搭建自己的图床" aria-label="Permalink to &quot;用 GitHub + PicGo 搭建自己的图床&quot;">​</a></h1><p>Typora 默认把图片存在本地，文章发到网上后图片自然就裂了。图床要解决的就是这件事：插入图片时自动上传，正文里只保留一个可公开访问的 URL。</p><h2 id="一、为什么选-github" tabindex="-1">一、为什么选 GitHub <a class="header-anchor" href="#一、为什么选-github" aria-label="Permalink to &quot;一、为什么选 GitHub&quot;">​</a></h2><p>按存放方式来分，常见的图床有三类：</p><table tabindex="0"><thead><tr><th>类型</th><th>代表</th><th>特点</th></tr></thead><tbody><tr><td>公共图床</td><td>SM.MS、路过图床</td><td>免注册或注册即用，但稳定性和长期性不由自己控制</td></tr><tr><td>代码托管平台</td><td>GitHub、Gitee</td><td>仓库即图床，可控、免费，缺点是国内直连慢</td></tr><tr><td>对象存储 / 云服务器</td><td>阿里云 OSS、七牛云、自建</td><td>速度快、可绑定域名，但按量计费</td></tr></tbody></table><p>对学生和个人博客来说，GitHub 仓库是成本最低的选择：公开仓库免费、容量足够，配合 jsDelivr 的 CDN 还能缓解访问速度问题。Gitee 虽然国内快，但免费仓库对单文件大小和容量限制比较紧，不适合长期堆图。</p><h2 id="二、新建一个公开仓库" tabindex="-1">二、新建一个公开仓库 <a class="header-anchor" href="#二、新建一个公开仓库" aria-label="Permalink to &quot;二、新建一个公开仓库&quot;">​</a></h2><p>登录 GitHub，右上角 <code>+</code> → <code>New repository</code>，仓库名随意，例如 <code>pic</code>，可见性选 <strong>Public</strong>。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091501120.png" alt="新建仓库"></p><p>仓库必须公开，否则 jsDelivr 无法读取。私有仓库需要走带签名的私有资源地址，配置会麻烦很多。</p><h2 id="三、生成访问令牌" tabindex="-1">三、生成访问令牌 <a class="header-anchor" href="#三、生成访问令牌" aria-label="Permalink to &quot;三、生成访问令牌&quot;">​</a></h2><p>PicGo 需要凭令牌往仓库写文件。点击右上角头像 → <code>Settings</code>，左侧拉到最底，进入 <code>Developer settings</code>。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091504205.png" alt="Developer settings"></p><p>选择 <code>Personal access tokens</code> → <code>Tokens (classic)</code> → <code>Generate new token (classic)</code>。填写 Note 方便日后辨认，Expiration 按需选择，<strong>不建议选 No expiration</strong>，图床用多久就设多久。</p><p>权限只勾 <code>repo</code> 这一项即可，其余都不需要。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091506931.png" alt="选择权限"></p><p>生成后令牌只显示一次，先复制到安全的地方。它等同于仓库的写入权限，不要写进代码或提交到公开仓库。</p><blockquote><p>GitHub 现在也提供 Fine-grained tokens：可以选择单个仓库，并把权限收窄到 <code>Contents: Read and write</code>，比 classic token 更安全。只是配置项多一些，按需选择即可。</p></blockquote><h2 id="四、安装并配置-picgo" tabindex="-1">四、安装并配置 PicGo <a class="header-anchor" href="#四、安装并配置-picgo" aria-label="Permalink to &quot;四、安装并配置 PicGo&quot;">​</a></h2><p><a href="https://github.com/Molunerfinn/PicGo/releases" target="_blank" rel="noreferrer">PicGo</a> 是一个跨平台的图床上传工具，拖入图片就能得到链接。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091507760.png" alt="PicGo Releases"></p><p>安装完成后，打开 <code>图床设置</code> → <code>GitHub</code>。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091508317.png" alt="PicGo 图床设置"></p><p>这是新版的UI，如图配置 <img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/0be69372-9ab3-4fe5-bd22-444e416d8d48.png" alt=""> 按下面几项填写：</p><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>图床配置名</td><td>自定义，例如 <code>github</code></td></tr><tr><td>仓库名</td><td><code>用户名/仓库名</code>，例如 <code>jokerxian/pic</code></td></tr><tr><td>分支名</td><td><code>main</code>（GitHub 新建仓库的默认分支）</td></tr><tr><td>Token</td><td>上一步生成的令牌</td></tr><tr><td>存储路径</td><td>仓库内的目录，例如 <code>pics/</code></td></tr><tr><td>自定义域名</td><td>jsDelivr 地址，见下一节</td></tr></tbody></table><p>存储路径有几个约定：放在根目录就留空；多级目录直接写 <code>img/2026/</code> 这样的相对路径，前面不要加 <code>/</code>；目录不存在时 PicGo 会自动创建。<strong>建议路径末尾统一带上 <code>/</code></strong>，否则 PicGo 会把本地文件名拼到路径后面，得到 <code>pics20240709.png</code> 这种结果。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091509435.png" alt="PicGo 配置示例"></p><h2 id="五、用-jsdelivr-加速" tabindex="-1">五、用 jsDelivr 加速 <a class="header-anchor" href="#五、用-jsdelivr-加速" aria-label="Permalink to &quot;五、用 jsDelivr 加速&quot;">​</a></h2><p>jsdelivr地址：<a href="https://cdn.jsdelivr.net" target="_blank" rel="noreferrer">https://cdn.jsdelivr.net</a></p><p>GitHub 的原始文件地址在国内访问经常很慢，jsDelivr 把仓库内容缓存到 CDN 边缘节点，读取速度会好很多。它的 GitHub 地址格式是固定的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/用户名/仓库名@分支/文件路径</span></span></code></pre></div><p><code>@分支</code> 在仓库默认分支时可以省略。对应到 PicGo 的「自定义域名」，填到仓库名为止即可，文件名由 PicGo 自动追加：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/jokerxian/pic</span></span></code></pre></div><p>如果图片要传到非默认分支，才需要写成 <code>https://cdn.jsdelivr.net/gh/jokerxian/pic@test</code>。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/0ce5caa21fd5c6b64484ca45c879b145.png" alt=""></p><p>需要注意的是，jsDelivr 在国内的可用性这几年有波动，偶尔会出现解析失败或加载缓慢。遇到这种情况，可以先换成自定义域名直连仓库，或者搭一层自己的 CDN；图片本身在 GitHub 上，不会丢。</p><h2 id="六、测试上传" tabindex="-1">六、测试上传 <a class="header-anchor" href="#六、测试上传" aria-label="Permalink to &quot;六、测试上传&quot;">​</a></h2><p>配置保存后，在 PicGo 里把图片拖进上传区，或在相册页点击上传。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091513960.png" alt="上传测试"></p><p>上传成功后可以在相册里查看图片、复制 URL 或删除。建议点开链接确认一次，能正常显示再继续下一步。</p><h2 id="七、接入-typora" tabindex="-1">七、接入 Typora <a class="header-anchor" href="#七、接入-typora" aria-label="Permalink to &quot;七、接入 Typora&quot;">​</a></h2><p>打开 Typora 的 <code>偏好设置</code> → <code>图像</code>：</p><ul><li>「插入图片时」选择 <code>上传图片</code>；</li><li>「上传服务」选择 <code>PicGo</code>，并指定 <code>PicGo.exe</code> 的安装路径；</li><li>按需勾选「对本地图片应用上述规则」和「对网络图片应用上述规则」。</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091514181.png" alt="Typora 图像设置"></p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091514741.png" alt="指定 PicGo 路径"></p><p>之后在 Typora 里粘贴或拖入图片，就会自动上传并替换成网络链接。如果上传失败，先检查 PicGo 是否能独立上传，再排查 Typora 的路径是否选对。</p><p>另外，如果本机开着 Steam++、Watt Toolkit 这类会接管 GitHub 流量的加速工具，上传时可能会报证书或连接错误，临时关闭再试。</p><h2 id="八、几个细节" tabindex="-1">八、几个细节 <a class="header-anchor" href="#八、几个细节" aria-label="Permalink to &quot;八、几个细节&quot;">​</a></h2><p><strong>开启时间戳重命名。</strong> 在 PicGo 设置里打开后，同名图片不会互相覆盖，避免旧文章里的图被新图替换。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/202407091513502.png" alt="时间戳重命名"></p><p><strong>控制仓库体积。</strong> GitHub 建议单个仓库保持在 1GB 以内、单文件不超过 100MB。图片多的仓库最好按年份或主题分目录，必要时再考虑压缩。</p><p><strong>注意 CDN 缓存。</strong> jsDelivr 会缓存资源，替换同名图片后短时间内可能仍显示旧图，换个文件名最省事。</p><p><strong>PicGo 更新较慢。</strong> 如果遇到新系统兼容问题，可以试试它的活跃分支 <a href="https://github.com/Kuingsmile/PicList" target="_blank" rel="noreferrer">PicList</a>，配置项基本兼容，迁移成本很低。</p><h2 id="九、小结" tabindex="-1">九、小结 <a class="header-anchor" href="#九、小结" aria-label="Permalink to &quot;九、小结&quot;">​</a></h2><p>整套流程只做一次：建公开仓库、生成只含 <code>repo</code> 权限的令牌、在 PicGo 里填好仓库和 jsDelivr 域名、最后让 Typora 调用 PicGo。之后写作时只需粘贴图片，剩下的交给工具。</p><p>真正需要留心的是安全与长期性：令牌别泄露、仓库别转私有、CDN 失效时知道去哪里改。图床不是一劳永逸的服务，但自己掌控数据，至少不会因为某个公共图床关停而丢图。</p>',56)])])}const b=e(r,[["render",c]]);export{g as __pageData,b as default};
